import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

// Keep the audit engine authoritative in modules/. Studio packages only
// app/agent/, so generate a deploy-local copy before compilation.
const root = new URL('../', import.meta.url);
const source = new URL('modules/bnb-agent/src/auditor.ts', root);
const targetDir = new URL('studio/lvxterminator/app/agent/src/bnb/', root);
await mkdir(targetDir, { recursive: true });
const content = await readFile(source, 'utf8');
await writeFile(new URL('auditor.ts', targetDir),
  '// GENERATED by scripts/studio-sync.mjs. Edit modules/bnb-agent/src/auditor.ts.\n' + content);
console.log(`Studio audit engine synchronized: ${fileURLToPath(targetDir)}`);
